import math as _m
def _close(a, b, tol=1e-9):
    if isinstance(a, (list, tuple)):
        return len(a) == len(b) and all(_close(x, y, tol) for x, y in zip(a, b))
    return abs(a - b) < tol
def _ref(Q, K, V, causal=False):
    d = len(K[0]); W = []
    for i, q in enumerate(Q):
        s = [sum(a * b for a, b in zip(q, k)) / _m.sqrt(d) if not (causal and j > i) else float("-inf") for j, k in enumerate(K)]
        mx = max(s); e = [_m.exp(x - mx) for x in s]; t = sum(e); W.append([x / t for x in e])
    return [[sum(w * v[c] for w, v in zip(row, V)) for c in range(len(V[0]))] for row in W], W
